    links: [["National Careers Service – laboratory technician", "https://nationalcareers.service.gov.uk/job-profiles/laboratory-technician"], ["Find an apprenticeship – laboratory and science", "https://www.findapprenticeship.service.gov.uk/apprenticeships?searchTerm=laboratory&location=Margate&distance=30"], ["GOV.UK – Free courses for jobs", "https://www.gov.uk/free-courses-for-jobs"]],
