    needs: {"experience": "None for production and packing roles.", "quals": "None to start. Employers train you on machines and safety. Free Level 2 manufacturing courses help you move up.", "card": ""},
    steps: [{"t": "Talk to your work coach", "d": "Ask about manufacturing SWAPs and free Level 2 courses, and whether a Sector-based Work Academy (SWAP) or Skills Bootcamp is running locally. They may also help with costs through the Flexible Support Fund."}, {"t": "Apply for production operative roles", "d": "Agencies and factories hire all year, especially before Christmas."}, {"t": "Show you are reliable on shifts", "d": "Turning up for every shift is what factories value most."}, {"t": "Learn more machines", "d": "Ask to train on different lines, forklifts or quality checks."}, {"t": "Grow your career", "d": "Team leader, setter, maintenance or a manufacturing apprenticeship."}],
